DO $$ DECLARE v_investment uuid; v_source uuid; BEGIN SELECT id INTO v_investment FROM public.investments WHERE symbol='VUN' LIMIT 1; IF v_investment IS NULL THEN RAISE EXCEPTION 'VUN not found'; END IF; INSERT INTO public.investment_data_sources(investment_id,source_name,source_type,source_url,metric_scope,retrieved_at,source_version,notes) VALUES (v_investment,'Vanguard Canada','official','https://www.vanguard.ca/en/product/etf/equity/9557/vanguard-us-total-market-index-etf','profile,metrics,risk,price,holdings',now(),'2026-09','Official Vanguard product page/factsheet; supplemental current performance/risk cross-check from public market data sources.') RETURNING id INTO v_source; INSERT INTO public.investment_metrics(investment_id,as_of_date,price,return_1y_pct,yield_pct,distribution_frequency,mer_pct,aum) VALUES (v_investment,'2026-09-02',142.52,20.75,0.76,'quarterly',0.17,19.62e9); INSERT INTO public.investment_risk_metrics(investment_id,as_of_date,risk_level,volatility_3y_pct,beta,sharpe_ratio,max_drawdown_3y_pct) VALUES (v_investment,'2026-07-31','High',12.51,1.02,1.31,-13.10); INSERT INTO public.investment_price_history(investment_id,price_date,close_price,currency,source_id) VALUES (v_investment,'2026-09-11',142.52,'CAD',v_source),(v_investment,'2026-09-10',143.29,'CAD',v_source),(v_investment,'2026-09-09',142.70,'CAD',v_source); INSERT INTO public.investment_holdings(investment_id,as_of_date,holding_symbol,holding_name,country_code,asset_type,weight_pct,source_id) VALUES (v_investment,'2026-05-31','VTI','Vanguard Total Stock Market Index ETF','US','ETF',100.00,v_source); UPDATE public.investment_profiles SET source_id=v_source,as_of_date='2026-05-31',benchmark='CRSP US Total Market Index',updated_at=now() WHERE investment_id=v_investment; UPDATE public.investments SET data_status='verified_partial',updated_at=now() WHERE id=v_investment; END $$; SELECT public.refresh_investment_data_quality();